declare patches constant jsonb:=$shared_rows$[{"table":"ancestry","id":3,"before":{"id":3,"name":"Elf","uuid":"6069556547543259","rarity":"COMMON","version":"1.0","trait_id":1348,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=60","book":"Player Core","page":"46"}},"created_at":"2023-12-02T22:15:58.556798+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":6,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":30,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":84},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Draconic\",\n  \"Empyrean\",\n  \"Fey\",\n  \"Gnomish\",\n  \"Goblin\",\n  \"Kholo\",\n  \"Orcish\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":19330},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_DEX"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_INT"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"13e39aad-cd73-4b63-ae9b-2f8e5b0c12e3","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-elf-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Elves are a tall, long-lived people with a strong tradition of art and magic._\n\nAs an ancient people, elves have seen great change and have the perspective that can come only from watching the arc of history. After leaving Golarion in ancient times, they returned to a changed land, and they still struggle to reclaim their ancestral homes. Elves value kindness, intellect, and beauty, with many elves striving to improve their manners, appearance, and culture. Their studies delve into a level of detail that most shorter-lived peoples find excessive or inefficient. Elves are often rather private people, steeped in the secrets of their groves and kinship groups. They're slow to build friendships outside their kinsfolk, as elves who spend their lives among shorter-lived peoples often become morose after watching generations of companions age and die. These elves are known as Forlorn among their fellow elves.\n\nIf you want a character who is [magical](link_trait_1504), mystical, and mysterious, you should play an elf.","content_source_id":1},"after":{"id":3,"name":"Elf","uuid":"1585905187237552","rarity":"COMMON","version":"1.0","trait_id":1348,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=60","book":"Player Core","page":"46"}},"created_at":"2023-12-02T22:15:58.556798+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":6,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":30,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":84},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Draconic\",\n  \"Empyrean\",\n  \"Fey\",\n  \"Gnomish\",\n  \"Goblin\",\n  \"Kholo\",\n  \"Orcish\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":19330},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_DEX"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_INT"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"13e39aad-cd73-4b63-ae9b-2f8e5b0c12e3","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-elf-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Elves are a tall, long-lived people with a strong tradition of art and magic._\n\nAs an ancient people, elves have seen great change and have the perspective that can come only from watching the arc of history. After leaving Golarion in ancient times, they returned to a changed land, and they still struggle to reclaim their ancestral homes. Elves value kindness, intellect, and beauty, with many elves striving to improve their manners, appearance, and culture. Their studies delve into a level of detail that most shorter-lived peoples find excessive or inefficient. Elves are often rather private people, steeped in the secrets of their groves and kinship groups. They're slow to build friendships outside their kinsfolk, as elves who spend their lives among shorter-lived peoples often become morose after watching generations of companions age and die. These elves are known as Forlorn among their fellow elves.\n\nIf you want a character who is [magical](link_trait_1504), mystical, and mysterious, you should play an elf.","content_source_id":3}},{"table":"ancestry","id":4,"before":{"id":4,"name":"Dwarf","uuid":"518845481186385","rarity":"COMMON","version":"1.0","trait_id":1467,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=59","book":"Player Core","page":"42"}},"created_at":"2023-12-14T04:35:20.980759+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":10,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":20,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_CHA"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":83},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Gnomish\",\n  \"Goblin\",\n  \"Jotun\",\n  \"Orcish\",\n  \"Petran\",\n  \"Sakvroth\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":20769},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_WIS"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"802db98f-dfe6-4dac-b370-650edb781046","data":{"type":"physical-feature","abilityBlockId":20771},"type":"giveAbilityBlock"},{"id":"1cfee0a2-58bd-41d0-9b56-6b1ec041198a","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-dwarf-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Dwarves are a short, stocky people who are often stubborn, fierce, and devoted._\n\nDwarves have a well-earned reputation as a stoic and stern people, but they also have an unbridled zeal and deeply value artisanship. To a stranger, they can seem untrusting and clannish, but to their friends and family, they are warm and caring. While trust from a dwarf is hard-won, once gained it is as strong as iron.\n\nIf you want to play a character who is as hard as nails, a stubborn and unrelenting adventurer, with a mix of rugged toughness and deep wisdom, you should play a dwarf.","content_source_id":1},"after":{"id":4,"name":"Dwarf","uuid":"8318269341451140","rarity":"COMMON","version":"1.0","trait_id":1467,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=59","book":"Player Core","page":"42"}},"created_at":"2023-12-14T04:35:20.980759+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":10,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":20,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_CHA"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":83},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Gnomish\",\n  \"Goblin\",\n  \"Jotun\",\n  \"Orcish\",\n  \"Petran\",\n  \"Sakvroth\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":20769},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_WIS"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"802db98f-dfe6-4dac-b370-650edb781046","data":{"type":"physical-feature","abilityBlockId":20771},"type":"giveAbilityBlock"},{"id":"1cfee0a2-58bd-41d0-9b56-6b1ec041198a","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-dwarf-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Dwarves are a short, stocky people who are often stubborn, fierce, and devoted._\n\nDwarves have a well-earned reputation as a stoic and stern people, but they also have an unbridled zeal and deeply value artisanship. To a stranger, they can seem untrusting and clannish, but to their friends and family, they are warm and caring. While trust from a dwarf is hard-won, once gained it is as strong as iron.\n\nIf you want to play a character who is as hard as nails, a stubborn and unrelenting adventurer, with a mix of rugged toughness and deep wisdom, you should play a dwarf.","content_source_id":3}},{"table":"ancestry","id":5,"before":{"id":5,"name":"Gnome","uuid":"2257579532369643","rarity":"COMMON","version":"1.0","trait_id":1452,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=61","book":"Player Core","page":"50"}},"created_at":"2023-12-14T04:38:09.147639+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":8,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"small","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":25,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_STR"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":90},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Dwarven\",\n  \"Draconic\",\n  \"Elven\",\n  \"Goblin\",\n  \"Jotun\",\n  \"Orcish\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":19330},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_CHA"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"cdd84645-ffd4-455b-86ff-a8402b15f8c6","data":{"languageId":85},"type":"giveLanguage"},{"id":"74a80d85-13d4-4895-a027-699bef17fc6b","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-gnome-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Gnomes are short and hardy folk, with an unquenchable curiosity and eccentric habits._\n\nLong ago, early gnome ancestors emigrated from the First World, realm of the [fey](link_trait_2021). While it's unclear why the first gnomes wandered to Golarion, this lineage manifests in modern gnomes as bizarre reasoning, eccentricity, obsessive tendencies, and what some see as naivete.\n\nAlways hungry for new experiences, gnomes constantly wander both mentally and physically, attempting to stave off a terrible ailment that threatens all of their people. This affliction, known as the Bleaching, strikes gnomes who fail to dream, innovate, and take in new experiences. The Bleaching slowly drains the color— literally—from gnomes, and it plunges those affected into states of deep depression that eventually claim their lives. Very few gnomes survive this scourge, becoming deeply morose and wise survivors known as bleachlings.\n\nIf you want a character with boundless enthusiasm and an alien, fey outlook on morality and life, you should play a gnome.","content_source_id":1},"after":{"id":5,"name":"Gnome","uuid":"6314421069635444","rarity":"COMMON","version":"1.0","trait_id":1452,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=61","book":"Player Core","page":"50"}},"created_at":"2023-12-14T04:38:09.147639+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":8,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"small","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":25,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_STR"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":90},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Dwarven\",\n  \"Draconic\",\n  \"Elven\",\n  \"Goblin\",\n  \"Jotun\",\n  \"Orcish\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":19330},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_CHA"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"cdd84645-ffd4-455b-86ff-a8402b15f8c6","data":{"languageId":85},"type":"giveLanguage"},{"id":"74a80d85-13d4-4895-a027-699bef17fc6b","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-gnome-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Gnomes are short and hardy folk, with an unquenchable curiosity and eccentric habits._\n\nLong ago, early gnome ancestors emigrated from the First World, realm of the [fey](link_trait_2021). While it's unclear why the first gnomes wandered to Golarion, this lineage manifests in modern gnomes as bizarre reasoning, eccentricity, obsessive tendencies, and what some see as naivete.\n\nAlways hungry for new experiences, gnomes constantly wander both mentally and physically, attempting to stave off a terrible ailment that threatens all of their people. This affliction, known as the Bleaching, strikes gnomes who fail to dream, innovate, and take in new experiences. The Bleaching slowly drains the color— literally—from gnomes, and it plunges those affected into states of deep depression that eventually claim their lives. Very few gnomes survive this scourge, becoming deeply morose and wise survivors known as bleachlings.\n\nIf you want a character with boundless enthusiasm and an alien, fey outlook on morality and life, you should play a gnome.","content_source_id":3}},{"table":"ancestry","id":6,"before":{"id":6,"name":"Goblin","uuid":"5310427347615682","rarity":"COMMON","version":"1.0","trait_id":1468,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=62","book":"Player Core","page":"54"}},"created_at":"2023-12-14T04:41:20.25442+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":6,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"small","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":25,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_WIS"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":86},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Dwarven\",\n  \"Draconic\",\n  \"Gnomish\",\n  \"Halfling\",\n  \"Orcish\",\n  \"Kholo\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":20769},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_DEX"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_CHA"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"b2c01cdb-3d57-4309-98a1-1837b9ef3771","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-goblin-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Goblins are a short, scrappy, energetic people who have spent millennia maligned and feared._\n\nThe convoluted histories other people cling to don't interest goblins. These small folk live in the moment, and they prefer tall tales over factual records. Goblin virtues are about being present, creative, and honest. They strive to lead fulfilled lives, rather than worrying about how their journeys will end. To tell stories, not nitpick the facts. To be small, but dream big. Many goblins enjoy simpler delights like songs, fire, and eating, and hate reading, dogs, and horses. Other goblins might have more complex pursuits, though, such as tinkering with scraps or concocting snacks and explosives from most anything.\n\nIf you want a character who is eccentric, enthusiastic, and fun-loving, you should play a goblin.","content_source_id":1},"after":{"id":6,"name":"Goblin","uuid":"1570287111767689","rarity":"COMMON","version":"1.0","trait_id":1468,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=62","book":"Player Core","page":"54"}},"created_at":"2023-12-14T04:41:20.25442+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":6,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"small","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":25,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_WIS"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e16779