 p jsonb; row jsonb; before_count integer:=0;after_count integer:=0;changed integer;
begin
 if (exists(select 1 from pg_catalog.pg_proc p
  where p.oid=pg_catalog.to_regprocedure('public.treasure_vault_terminal_status_v1()')
    and pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to((p.prosrc)::text,'UTF8')),'hex')='fbdf75894b97980ba3382a2a74ee2dd8f28929a129b21ca423942e0aeba544b2'
    and p.prokind='f' and p.prolang=(select l.oid from pg_catalog.pg_language l where l.lanname='sql')
    and p.provolatile='s' and p.prosecdef is false and p.proisstrict is false and p.proleakproof is false
    and p.proparallel='u' and p.procost=100 and p.prorows=1
    and p.pronargs=0 and p.pronargdefaults=0 and p.proretset is true
    and p.prorettype=pg_catalog.to_regtype('record')
    and p.proallargtypes=array[pg_catalog.to_regtype('boolean')::oid,pg_catalog.to_regtype('boolean')::oid]
    and p.proargmodes=array['t','t']::"char"[] and p.proargnames=array['recognized','passed']::text[]
    and p.proconfig=array['search_path=""']::text[] and p.proowner=pg_catalog.to_regrole('postgres')
    and (select count(*)=3
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('postgres'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('service_role'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('supabase_read_only_user'))=1
      and bool_and((a.privilege_type='EXECUTE' and a.is_grantable is false
      and a.grantor=pg_catalog.to_regrole('postgres')
      and a.grantee in(pg_catalog.to_regrole('postgres'),pg_catalog.to_regrole('service_role'),pg_catalog.to_regrole('supabase_read_only_user'))) is true)
      from pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a)
    and pg_catalog.has_function_privilege('postgres',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('supabase_read_only_user',p.oid,'EXECUTE'))) is not true then raise exception 'Shared ancestry helper differs'; end if;
 if not exists(select 1 from public.treasure_vault_terminal_status_v1() where recognized is true and passed is true) then raise exception 'Shared ancestry preflight differs'; end if;
 if not exists(select 1 from public.content_source where id=3 and name='Common Core' and user_id is null and is_published is true and deprecated is not true) then raise exception 'Shared ancestry source differs'; end if;
 for p in select value from jsonb_array_elements(patches) loop
  if p->>'table' not in('ancestry','trait') then raise exception 'Unexpected shared ancestry table'; end if;
  execute format('select (to_jsonb(r)-''updated_at''-''search_tsv'')||jsonb_build_object(''uuid'',r.uuid::text) from public.%I r where id=$1 for update',p->>'table') into row using (p->>'id')::bigint;
  if row=p->'before' then before_count:=before_count+1; end if;
  if row=p->'after' then after_count:=after_count+1; end if;
 end loop;
 if before_count<>12 and after_count<>12 then raise exception 'Shared ancestry rows are partial or changed'; end if;
 if after_count=12 then return; end if;
 for p in select value from jsonb_array_elements(patches) loop
  execute format('update public.%I set content_source_id=3,uuid=$1 where id=$2',p->>'table') using (p#>>'{after,uuid}')::bigint,(p->>'id')::bigint;
  get diagnostics changed=row_count;
  if changed<>1 then raise exception 'Shared ancestry write count differs'; end if;
  execute format('select (to_jsonb(r)-''updated_at''-''search_tsv'')||jsonb_build_object(''uuid'',r.uuid::text) from public.%I r where id=$1',p->>'table') into row using (p->>'id')::bigint;
  if row is distinct from p->'after' then raise exception 'Shared ancestry readback differs'; end if;
 end loop;
 if not exists(select 1 from public.treasure_vault_terminal_status_v1() where recognized is true and passed is true) then raise exception 'Shared ancestry final check differs'; end if;
end $shared_move$;
commit;
